export const MAX_INT = 2147483647;

export class ApiError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

const JSON_HEADERS = { 'content-type': 'application/json; charset=utf-8' };

export function json(body, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: JSON_HEADERS });
}

export function errorResponse(status, message) {
  return json({ error: message }, status);
}

// Wraps a route handler: ApiError becomes its status and JSON error, anything else is a 500.
export function route(fn) {
  return async (request, context) => {
    try {
      return await fn(request, context);
    } catch (err) {
      if (err instanceof ApiError) return errorResponse(err.status, err.message);
      console.error(err);
      return errorResponse(500, 'internal server error');
    }
  };
}

export function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

// Path ids: anything malformed or out of range is "not found".
export function parseId(raw) {
  if (typeof raw !== 'string' || !/^\d+$/.test(raw)) return null;
  const id = Number(raw);
  return Number.isSafeInteger(id) && id >= 1 && id <= MAX_INT ? id : null;
}

function parseIntegerParam(raw, name, min, max) {
  if (!/^\d+$/.test(raw)) throw new ApiError(400, `${name} must be an integer`);
  const n = Number(raw);
  if (!Number.isSafeInteger(n) || n < min || n > max) {
    throw new ApiError(400, `${name} must be between ${min} and ${max}`);
  }
  return n;
}

export function parsePaging(searchParams) {
  let page = 1;
  let itemsPerPage = 10;
  if (searchParams.has('page')) {
    page = parseIntegerParam(searchParams.get('page'), 'page', 1, MAX_INT);
  }
  if (searchParams.has('itemsPerPage')) {
    itemsPerPage = parseIntegerParam(searchParams.get('itemsPerPage'), 'itemsPerPage', 1, 50);
  }
  return { page, itemsPerPage, offset: (page - 1) * itemsPerPage };
}

export function listEnvelope(items, total, paging) {
  return { items, total, page: paging.page, itemsPerPage: paging.itemsPerPage };
}

// Optional signed integer query parameter; a present but malformed value is a 400.
export function optionalInteger(searchParams, key) {
  if (!searchParams.has(key)) return null;
  const raw = searchParams.get(key);
  if (!/^-?\d+$/.test(raw)) throw new ApiError(400, `${key} must be an integer`);
  const n = Number(raw);
  if (!Number.isSafeInteger(n)) throw new ApiError(400, `${key} is out of range`);
  return n;
}

// Returns the date as YYYY-MM-DD, or null when it is not a real calendar date.
export function parseDate(raw) {
  if (typeof raw !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(raw)) return null;
  const d = new Date(`${raw}T00:00:00Z`);
  if (Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== raw) return null;
  return raw;
}

export function optionalDate(searchParams, key) {
  if (!searchParams.has(key)) return null;
  const date = parseDate(searchParams.get(key));
  if (date === null) throw new ApiError(400, `${key} must be a date YYYY-MM-DD`);
  return date;
}

export async function readJson(request) {
  try {
    return await request.json();
  } catch {
    throw new ApiError(400, 'request body must be valid JSON');
  }
}

