import { pool, query } from './db';
import { ApiError, MAX_INT, isPlainObject, listEnvelope, parseId, parsePaging } from './api';

const PAYMENT_URL = 'http://127.0.0.1:18090/payments';
const PAYMENT_TIMEOUT_MS = 5000;

// Customer identification: missing, malformed or unknown ids answer 401.
export async function requireCustomer(request) {
  const raw = request.headers.get('x-customer-id');
  const id = raw === null ? null : parseId(raw);
  if (id === null) throw new ApiError(401, 'missing or invalid X-Customer-Id header');
  const { rows } = await query('SELECT id FROM customer WHERE id = $1', [id]);
  if (rows.length === 0) throw new ApiError(401, 'unknown customer');
  return id;
}

function purchaseShape(row, lines) {
  return {
    id: row.id,
    createdAt: new Date(row.created_at).toISOString(),
    totalCents: row.total_cents,
    lines,
  };
}

async function withLines(rows) {
  if (rows.length === 0) return [];
  const { rows: lineRows } = await query(
    `SELECT pl.purchase_id, pl.book_id, b.title, pl.quantity, pl.unit_price_cents
     FROM purchase_line pl
     JOIN book b ON b.id = pl.book_id
     WHERE pl.purchase_id = ANY($1::int[])
     ORDER BY pl.id`,
    [rows.map((r) => r.id)],
  );
  const linesByPurchase = new Map(rows.map((r) => [r.id, []]));
  for (const l of lineRows) {
    linesByPurchase.get(l.purchase_id).push({
      bookId: l.book_id,
      title: l.title,
      quantity: l.quantity,
      unitPriceCents: l.unit_price_cents,
    });
  }
  return rows.map((r) => purchaseShape(r, linesByPurchase.get(r.id)));
}

export async function listPurchases(customerId, searchParams) {
  const paging = parsePaging(searchParams);
  const count = await query('SELECT count(*) AS total FROM purchase WHERE customer_id = $1', [customerId]);
  const { rows } = await query(
    `SELECT id, created_at, total_cents FROM purchase
     WHERE customer_id = $1
     ORDER BY created_at DESC, id DESC
     LIMIT $2 OFFSET $3`,
    [customerId, paging.itemsPerPage, paging.offset],
  );
  return listEnvelope(await withLines(rows), Number(count.rows[0].total), paging);
}

export async function findPurchase(customerId, id) {
  const { rows } = await query(
    'SELECT id, created_at, total_cents FROM purchase WHERE id = $1 AND customer_id = $2',
    [id, customerId],
  );
  if (rows.length === 0) return null;
  const [purchase] = await withLines(rows);
  return purchase;
}

function validateLines(body) {
  if (!isPlainObject(body) || !Array.isArray(body.lines) || body.lines.length === 0) {
    throw new ApiError(422, 'lines must be a non-empty array');
  }
  return body.lines.map((line) => {
    if (!isPlainObject(line) || !isInRange(line.bookId) || !isInRange(line.quantity)) {
      throw new ApiError(422, 'each line needs an integer bookId and a quantity of at least 1');
    }
    return { bookId: line.bookId, quantity: line.quantity };
  });
}

function isInRange(value) {
  return Number.isSafeInteger(value) && value >= 1 && value <= MAX_INT;
}

async function requestPayment(customerId, amountCents) {
  let response;
  try {
    response = await fetch(PAYMENT_URL, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ customerId, amountCents }),
      signal: AbortSignal.timeout(PAYMENT_TIMEOUT_MS),
    });
  } catch {
    throw new ApiError(502, 'payment service unavailable');
  }
  if (!response.ok) throw new ApiError(502, 'payment service failed');

  let answer;
  try {
    answer = await response.json();
  } catch {
    throw new ApiError(502, 'payment service gave an invalid answer');
  }
  if (answer?.status === 'accepted') return;
  if (answer?.status === 'declined') throw new ApiError(402, 'payment declined');
  throw new ApiError(502, 'payment service gave an invalid answer');
}

export async function createPurchase(customerId, body) {
  const lines = validateLines(body);
  const bookIds = [...new Set(lines.map((l) => l.bookId))].sort((a, b) => a - b);

  const wanted = new Map();
  for (const l of lines) wanted.set(l.bookId, (wanted.get(l.bookId) ?? 0) + l.quantity);

  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Row locks are held until COMMIT, so stock checks and decrements cannot interleave.
    const { rows: books } = await client.query(
      'SELECT id, title, price_cents, stock, published FROM book WHERE id = ANY($1::int[]) ORDER BY id FOR UPDATE',
      [bookIds],
    );
    const byId = new Map(books.map((b) => [b.id, b]));
    for (const id of bookIds) {
      const book = byId.get(id);
      if (!book || !book.published) throw new ApiError(422, `book ${id} is not available`);
    }
    for (const [id, quantity] of wanted) {
      if (byId.get(id).stock < quantity) throw new ApiError(409, `not enough stock for book ${id}`);
    }

