export async function salesReportCsv(searchParams) {
  const from = requiredDate(searchParams, 'from');
  const to = requiredDate(searchParams, 'to');
  if (from > to) throw new ApiError(400, 'from must not be after to');

  // Whole UTC days, both bounds included: [from 00:00, to + 1 day 00:00).
  const start = new Date(`${from}T00:00:00Z`).toISOString();
  const endDate = new Date(`${to}T00:00:00Z`);
  endDate.setUTCDate(endDate.getUTCDate() + 1);

  const { rows } = await query(
    `SELECT b.id, b.title, sum(pl.quantity)::int AS quantity,
            sum(pl.quantity * pl.unit_price_cents)::bigint AS revenue_cents
     FROM purchase_line pl
     JOIN purchase p ON p.id = pl.purchase_id
     JOIN book b ON b.id = pl.book_id
     WHERE p.created_at >= $1::timestamptz AND p.created_at < $2::timestamptz
     GROUP BY b.id, b.title
     ORDER BY revenue_cents DESC, b.title COLLATE "C" ASC, b.id ASC`,
    [start, endDate.toISOString()],
  );

  const lines = ['title,quantity,revenueCents'];
  for (const r of rows) {
    lines.push([r.title, r.quantity, r.revenue_cents].map(csvCell).join(','));
  }
  return `${lines.join('\n')}\n`;
}

