import { query } from './db';
import { ApiError, MAX_INT, isPlainObject, listEnvelope, optionalDate, optionalInteger, parsePaging } from './api';

const BOOK_SELECT = `
  SELECT b.id, b.title, b.price_cents, to_char(b.published_at, 'YYYY-MM-DD') AS published_at,
         b.stock, b.published, a.id AS author_id, a.name AS author_name
  FROM book b
  JOIN author a ON a.id = b.author_id`;

// "C" collation gives plain code point ordering, so titles sort the same everywhere.
const SORT_FIELDS = {
  priceCents: 'b.price_cents',
  title: 'b.title COLLATE "C"',
  publishedAt: 'b.published_at',
};

export function bookShape(row) {
  return {
    id: row.id,
    title: row.title,
    priceCents: row.price_cents,
    publishedAt: row.published_at,
    stock: row.stock,
    author: { id: row.author_id, name: row.author_name },
  };
}

export async function findBook(id, { publishedOnly = true } = {}) {
  const { rows } = await query(
    `${BOOK_SELECT} WHERE b.id = $1 ${publishedOnly ? 'AND b.published' : ''}`,
    [id],
  );
  return rows[0] ?? null;
}

export async function listBooks(searchParams) {
  const where = ['b.published'];
  const params = [];
  const param = (value) => {
    params.push(value);
    return `$${params.length}`;
  };

  if (searchParams.has('title')) {
    where.push(`strpos(lower(b.title), lower(${param(searchParams.get('title'))})) > 0`);
  }
  if (searchParams.has('author')) {
    where.push(`a.name = ${param(searchParams.get('author'))}`);
  }

  const priceGte = optionalInteger(searchParams, 'priceCents[gte]');
  if (priceGte !== null) where.push(`b.price_cents >= ${param(priceGte)}`);
  const priceLte = optionalInteger(searchParams, 'priceCents[lte]');
  if (priceLte !== null) where.push(`b.price_cents <= ${param(priceLte)}`);

  const after = optionalDate(searchParams, 'publishedAt[after]');
  if (after !== null) where.push(`b.published_at >= ${param(after)}`);
  const before = optionalDate(searchParams, 'publishedAt[before]');
  if (before !== null) where.push(`b.published_at <= ${param(before)}`);

  if (searchParams.has('inStock')) {
    const inStock = searchParams.get('inStock');
    if (inStock === 'true') where.push('b.stock > 0');
    else if (inStock === 'false') where.push('b.stock = 0');
    else throw new ApiError(400, 'inStock must be true or false');
  }

  const order = [];
  for (const [key, direction] of searchParams.entries()) {
    const match = /^order\[([^\]]*)\]$/.exec(key);
    if (!match) continue;
    const column = Object.prototype.hasOwnProperty.call(SORT_FIELDS, match[1])
      ? SORT_FIELDS[match[1]]
      : null;
    if (column === null) throw new ApiError(400, `unknown sort field ${match[1]}`);
    if (direction !== 'asc' && direction !== 'desc') {
      throw new ApiError(400, 'sort direction must be asc or desc');
    }
    order.push(`${column} ${direction.toUpperCase()} NULLS LAST`);
  }
  order.push('b.id ASC');

  const whereSql = `WHERE ${where.join(' AND ')}`;
  const paging = parsePaging(searchParams);
  const count = await query(
    `SELECT count(*) AS total FROM book b JOIN author a ON a.id = b.author_id ${whereSql}`,
    params,
  );
  const rows = await query(
    `${BOOK_SELECT} ${whereSql} ORDER BY ${order.join(', ')} LIMIT ${param(paging.itemsPerPage)} OFFSET ${param(paging.offset)}`,
    params,
  );
  return listEnvelope(rows.rows.map(bookShape), Number(count.rows[0].total), paging);
}

function isNonNegativeInt(value) {
  return Number.isSafeInteger(value) && value >= 0 && value <= MAX_INT;
}

// Partial update; returns the book, or null when the book is unpublished (answered with 204).
export async function patchBook(id, body) {
  if (!isPlainObject(body)) throw new ApiError(422, 'body must be a JSON object');

  const sets = [];
  const params = [];
  const set = (column, value) => {
    params.push(value);
    sets.push(`${column} = $${params.length}`);
  };

  if ('title' in body) {
    if (typeof body.title !== 'string' || body.title.length === 0) {
      throw new ApiError(422, 'title must be a non-empty string');
    }
    set('title', body.title);
  }
  if ('priceCents' in body) {
    if (!isNonNegativeInt(body.priceCents)) throw new ApiError(422, 'priceCents must be a non-negative integer');
    set('price_cents', body.priceCents);
  }
  if ('stock' in body) {
    if (!isNonNegativeInt(body.stock)) throw new ApiError(422, 'stock must be a non-negative integer');
    set('stock', body.stock);
  }

  if (sets.length > 0) {
    params.push(id);
    await query(`UPDATE book SET ${sets.join(', ')} WHERE id = $${params.length}`, params);
  }

  const row = await findBook(id, { publishedOnly: false });
  if (!row.published) return null;
  return bookShape(row);
}

